ST.xhtml:p:
R_Trriger1(CLK := g_biFeedingHomeOpen OR bFeedingHomeOpen);
R_Trriger2(CLK := g_biFeedingHomeClose);

IF R_Trriger1.Q THEN
  nSwitchState := 1;
  g_nBKCuttingState := 18;
  bHomeDone := FALSE;
  g_boFeedingHomeDone := FALSE;
  g_bPressurePipeSignal := FALSE;
END_IF;

IF R_Trriger2.Q THEN
  g_boFeedingHomeDone := FALSE;
END_IF;

CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  Feeding_Home.Execute := TRUE;
  Feeding_Home.Position := dHomePosition;
  Feeding_Home.HomingMode := nHomingMode;
  Feeding_Home.bCalibrationCam := g_bFeedingZero;
  IF Feeding_Home.Done THEN
    Feeding_Home.Execute := FALSE;
    nSwitchState := 2;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 10;
  END_IF;

  IF Feeding_Home.CommandAborted OR Feeding_Home.Error THEN
    Feeding_Home.Execute := FALSE;
    g_boFeedingHomeDone := FALSE;
    g_bPressurePipeSignal := FALSE;
    nSwitchState := 0;
  END_IF;
  2:
  FeedingAbs.Execute := TRUE;
  FeedingAbs.Position := dFeedingHomeOffset;
  FeedingAbs.Velocity := dFeedingHomeVel;

  IF FeedingAbs.Done THEN
    FeedingAbs.Execute := FALSE;
    Feeding_Home.Execute := FALSE;
    bHomeDone := TRUE;
    g_boFeedingHomeDone := TRUE;
    g_nBKCuttingState := 19;
    g_bPressurePipeSignal := TRUE;
    nSwitchState := 0;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 11;
  END_IF;

  IF FeedingAbs.CommandAborted OR FeedingAbs.Error THEN
    FeedingAbs.Execute := FALSE;
    g_boFeedingHomeDone := FALSE;
    g_bPressurePipeSignal := FALSE;
    nSwitchState := 0;
  END_IF;
  10:
  Feeding_Home.Execute := FALSE;
  Feeding_Stop.Execute := TRUE;
  IF Feeding_Stop.Done AND g_bPlcStartBuffer THEN
    Feeding_Stop.Execute := FALSE;
    nSwitchState := 1;
  END_IF;

  IF Feeding_Stop.CommandAborted OR Feeding_Stop.Error THEN
    Feeding_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
  11:
  FeedingAbs.Execute := FALSE;
  Feeding_Stop.Execute := TRUE;
  IF Feeding_Stop.Done AND g_bPlcStartBuffer THEN
    Feeding_Stop.Execute := FALSE;
    nSwitchState := 2;
  END_IF;

  IF Feeding_Stop.CommandAborted OR Feeding_Stop.Error THEN
    Feeding_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
END_CASE;

g_nofeedState0 := nSwitchState;

IF g_bPlcResetBuffer THEN
  nSwitchState := 0;
  Feeding_Home.Execute := FALSE;
  Feeding_Stop.Execute := FALSE;
  FeedingAbs.Execute := FALSE;
  bHomeDone := TRUE;
  g_boFeedingHomeDone := FALSE;
END_IF;
